 @TempDir Path temp;CommunityStore store;AccessControl acl;AgentService agent;MutableClock clock;
 String admin,second,worker,other,publisher,workerRole;AtomicInteger published=new AtomicInteger();Map<String,Object>cfg;
 @BeforeEach void setup()throws Exception{
  clock=new MutableClock(Instant.parse("2026-10-15T12:00:00Z"));store=new CommunityStore(temp.resolve("community.sqlite"),clock);acl=new AccessControl(store);
  KeyPair a=key(),b=key();admin=identity(a);second=identity(b);acl.bootstrap(a.getPublic().getEncoded(),admin,b.getPublic().getEncoded(),second);
  worker=identity(key());other=identity(key());publisher=identity(key());workerRole=grant(worker,Set.of("AGENT_WORK"));grant(other,Set.of("AGENT_WORK"));grant(publisher,Set.of("NEWS_CREATE","NEWS_PUBLISH"));
  agent=new AgentService(store,acl,(actor,draft)->{acl.require(actor,"NEWS_CREATE","GLOBAL");if(Boolean.TRUE.equals(draft.get("autoPublish")))acl.require(actor,"NEWS_PUBLISH","GLOBAL");if(draft.get("distribution").equals("GLOBAL"))acl.require(actor,"NEWS_GLOBAL_PUBLISH","GLOBAL");published.incrementAndGet();return Map.of("id",UUID.randomUUID().toString(),"state",Boolean.TRUE.equals(draft.get("autoPublish"))?"PUBLISHED":"SUBMITTED");},(policy,observations,draft)->new AgentService.EvidenceProof(true,"LOCAL_FIXTURE_PROOF",List.of()));
  cfg=config();saveConfig();store.tx(db->{exec(db,"INSERT INTO agent_city(id,name) VALUES('ru/ru-mow/moscow','Москва'),('us/id/moscow','Москва')");for(int n=0;n<2;n++)exec(db,"INSERT INTO agent_source(id,url,city,source_group,official,enabled,min_interval,lawful_basis) VALUES(?,?,?,?,1,1,15,'Fixture permission')",UUID.randomUUID().toString(),"https://source"+n+".example/rss","ru/ru-mow/moscow","group"+n);exec(db,"INSERT INTO agent_worker(identity,enabled) VALUES(?,1),(?,1)",worker,other);return null;});
 }
 @AfterEach void close()throws Exception{if(agent!=null)agent.close();if(store!=null)store.close();}
 static KeyPair key()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
 String identity(KeyPair k)throws Exception{return store.ensureIdentity(k.getPublic().getEncoded(),"Тестовый пользователь");}
 String grant(String who,Set<String>rights)throws Exception{String id=UUID.randomUUID().toString();store.tx(db->{exec(db,"INSERT INTO roles(id,scope,name,clearance) VALUES(?,'GLOBAL',?,0)",id,id);for(String p:rights)exec(db,"INSERT INTO role_permissions VALUES(?,?)",id,p);exec(db,"INSERT INTO assignments VALUES(?,?)",who,id);return null;});return id;}
 Map<String,Object>config(){Map<String,Object>m=new LinkedHashMap<>();m.put("enabled",true);m.put("intervalMinutes",20);m.put("provider","ollama");m.put("model","fixture");m.put("endpoint","http://127.0.0.1:11434/api/chat");m.put("credentialRef","");m.put("publisherIdentity",publisher);m.put("maxOutputTokens",1024);m.put("dailyBudgetMicros",0);m.put("dailyRequestLimit",100);m.put("dailyTokenLimit",1000000);m.put("inputMicrosPerMillion",0);m.put("outputMicrosPerMillion",0);m.put("autoPublish",true);m.put("allowGlobal",false);return m;}
 void saveConfig()throws Exception{store.tx(db->{exec(db,"UPDATE agent_config SET data=? WHERE id=1",AgentJson.bytes(cfg));return null;});}
 @SuppressWarnings("unchecked")Map<String,Object>claim()throws Exception{agent.cycle();return (Map<String,Object>)agent.handle(worker,"agent.worker.claim",Map.of()).get("job");}
 @SuppressWarnings("unchecked")Map<String,Object>completion(Map<String,Object>job)throws Exception{
  List<Map<String,Object>>sources=(List<Map<String,Object>>)job.get("sources");List<Map<String,Object>>obs=new ArrayList<>();for(var s:sources)obs.add(new LinkedHashMap<>(Map.of("sourceId",s.get("id"),"sourceGroup",s.get("independenceGroup"),"official",s.get("official"),"cityId",s.get("cityId"),"title","Открытие библиотеки","text","Сегодня открывается городская библиотека. Независимое описание источника "+s.get("independenceGroup"),"url",s.get("url"),"publishedAt",clock.instant().toString(),"publicSource",true)));
  Map<String,Object>candidate=new LinkedHashMap<>(Map.of("title","В городе открывается библиотека","summary","Открывается библиотека. Источники независимо подтверждают событие.","cityId","ru/ru-mow/moscow","eventDate","2026-10-15","significance","ORDINARY","confidence",0.96,"contradictions",false,"citations",List.of(0,1)));
  Map<String,Object>d=new LinkedHashMap<>();d.put("jobId",job.get("id"));d.put("leaseToken",job.get("leaseToken"));d.put("observations",obs);d.put("analysis",new LinkedHashMap<>(Map.of("candidates",List.of(candidate))));d.put("inputTokens",100);d.put("outputTokens",20);d.put("fetchedSourceIds",sources.stream().map(s->s.get("id")).toList());return d;
 }
 @SuppressWarnings("unchecked")Map<String,Object>suggestion(Map<String,Object>d){return (Map<String,Object>)((List<?>)((Map<?,?>)d.get("analysis")).get("candidates")).get(0);}
 @Test void disabledAgentDoesNotGenerateFakePublications()throws Exception{cfg.put("enabled",false);saveConfig();agent.cycle();assertTrue(((Map<?,?>)agent.handle(worker,"agent.worker.claim",Map.of()).get("job")).isEmpty());assertEquals(0,published.get());}
 @Test void scheduleTwentyMinutesAndDistinctSameNamedCities()throws Exception{agent.cycle();agent.cycle();assertEquals(1,sqlLong("SELECT count(*) FROM agent_job"));clock.advance(Duration.ofMinutes(19));agent.cycle();assertEquals(1,sqlLong("SELECT count(*) FROM agent_job"));assertEquals(2,sqlLong("SELECT count(*) FROM agent_city"));}
