 @Test void completeAndRestartCannotDuplicatePublicationOrRefund()throws Exception{var j=claim();var d=completion(j);agent.handle(worker,"agent.worker.complete",d);agent.drainOutbox();agent.handle(worker,"agent.worker.complete",d);agent.close();agent=new AgentService(store,acl,(a,v)->{published.incrementAndGet();return Map.of("state","PUBLISHED","id","unexpected");});agent.drainOutbox();assertEquals(1,published.get());assertEquals(120,sqlLong("SELECT tokens FROM agent_budget"));}
 @Test void changedTitleCannotRepublishSameSourceEvidence()throws Exception{var j=claim();agent.handle(worker,"agent.worker.complete",completion(j));agent.drainOutbox();clock.advance(Duration.ofMinutes(21));var next=claim();var d=completion(next);suggestion(d).put("title","Библиотека открыта — другой заголовок");agent.handle(worker,"agent.worker.complete",d);agent.drainOutbox();assertEquals(1,published.get());}
 @Test void leaseIsBoundToWorkerAndCannotBeTakenTwice()throws Exception{var j=claim();assertTrue(((Map<?,?>)agent.handle(worker,"agent.worker.claim",Map.of()).get("job")).isEmpty());assertThrows(CommunityException.class,()->agent.handle(other,"agent.worker.complete",completion(j)));}
 @Test void expiredLeaseCannotCompleteAndRecoveryChargesNewReservation()throws Exception{var j=claim();clock.advance(Duration.ofMinutes(21));agent.cycle();assertThrows(CommunityException.class,()->agent.handle(worker,"agent.worker.complete",completion(j)));clock.advance(Duration.ofMinutes(2));var next=agent.handle(other,"agent.worker.claim",Map.of());assertFalse(((Map<?,?>)next.get("job")).isEmpty());assertEquals(2,sqlLong("SELECT requests FROM agent_budget"));}
 @Test void budgetReservedBeforeWorkAndRequestLimitsStopFurtherCalls()throws Exception{cfg.put("dailyRequestLimit",1);saveConfig();var j=claim();agent.handle(worker,"agent.worker.fail",Map.of("jobId",j.get("id"),"leaseToken",j.get("leaseToken"),"reason","MODEL_UNAVAILABLE"));clock.advance(Duration.ofMinutes(21));agent.cycle();assertTrue(((Map<?,?>)agent.handle(worker,"agent.worker.claim",Map.of()).get("job")).isEmpty());assertEquals(1,sqlLong("SELECT requests FROM agent_budget"));}
 @Test void monetaryBudgetStopsBeforeAnyExternalRequest()throws Exception{cfg.put("provider","openai-compatible");cfg.put("inputMicrosPerMillion",1000000);cfg.put("outputMicrosPerMillion",1000000);cfg.put("dailyBudgetMicros",1);saveConfig();assertTrue(claim().isEmpty());assertEquals(0,sqlLong("SELECT requests FROM agent_budget"));}
 @Test void revokedWorkerCannotSubmitCachedLease()throws Exception{var j=claim();store.tx(db->{exec(db,"DELETE FROM assignments WHERE identity=?",worker);return null;});assertThrows(CommunityException.class,()->agent.handle(worker,"agent.worker.complete",completion(j)));}
 @Test void workerCannotReadAdministrationOrPrivateLibrary()throws Exception{assertThrows(CommunityException.class,()->agent.handle(worker,"agent.sources.list",Map.of()));assertThrows(CommunityException.class,()->agent.handle(worker,"agent.review.list",Map.of()));assertThrows(CommunityException.class,()->agent.handle(worker,"agent.config.set",cfg));}
 @Test void privilegedIdentityCannotActAsNewsWorker()throws Exception{grant(worker,Set.of("NEWS_PUBLISH"));assertThrows(CommunityException.class,this::claim);}
 @Test void unknownModelToolInstructionsCannotBecomePublicationCommands()throws Exception{var j=claim();var d=completion(j);suggestion(d).put("execute","delete all roles");assertThrows(CommunityException.class,()->agent.handle(worker,"agent.worker.complete",d));assertEquals(0,sqlLong("SELECT count(*) FROM agent_candidate"));}
