 @Test void singleGroupImportantConflictsAndStaleDatesGoToReview()throws Exception{var j=claim();var d=completion(j);suggestion(d).put("significance","IMPORTANT");suggestion(d).put("contradictions",true);agent.handle(worker,"agent.worker.complete",d);agent.drainOutbox();assertEquals(1,sqlLong("SELECT count(*) FROM agent_candidate WHERE state='REVIEW'"));}
 @Test void stalePolicyRevisionRejectsWorkerCompletion()throws Exception{var j=claim();store.tx(db->{exec(db,"UPDATE agent_config SET revision=revision+1");return null;});assertThrows(CommunityException.class,()->agent.handle(worker,"agent.worker.complete",completion(j)));}
 @Test void sinkPermissionRevocationPreventsPublicationUntilRestored()throws Exception{var j=claim();agent.handle(worker,"agent.worker.complete",completion(j));store.tx(db->{exec(db,"DELETE FROM assignments WHERE identity=?",publisher);return null;});agent.drainOutbox();assertEquals(0,published.get());assertEquals(1,sqlLong("SELECT count(*) FROM agent_candidate WHERE state='PENDING'"));}
 @Test void configCannotBeMutatedWithClientFlagsOrWithoutStepUp()throws Exception{Map<String,Object> d=new LinkedHashMap<>(cfg);d.put("isAdmin",true);assertThrows(CommunityException.class,()->agent.handle(admin,"agent.config.set",d));d.remove("isAdmin");assertThrows(CommunityException.class,()->agent.handle(admin,"agent.config.set",d));}
 @Test void retryHasFiniteAttemptsAndExponentialBackoff()throws Exception{for(int n=0;n<4;n++){var j=claim();assertFalse(j.isEmpty());agent.handle(worker,"agent.worker.fail",Map.of("jobId",j.get("id"),"leaseToken",j.get("leaseToken"),"reason","SOURCE_UNAVAILABLE"));clock.advance(Duration.ofMinutes(21));}assertEquals(1,sqlLong("SELECT count(*) FROM agent_job WHERE state='FAILED'"));}
 @Test void rejectedIndependentCentralProofCannotAutoPublish()throws Exception{agent.close();agent=new AgentService(store,acl,(a,d)->{assertEquals(false,d.get("autoPublish"));assertEquals(false,d.get("verified"));return Map.of("state","SUBMITTED","id",UUID.randomUUID().toString());},(policy,observations,draft)->new AgentService.EvidenceProof(false,"SOURCE_CONTENT_MISMATCH",List.of()));var j=claim();agent.handle(worker,"agent.worker.complete",completion(j));agent.drainOutbox();assertEquals(1,sqlLong("SELECT count(*) FROM agent_candidate WHERE state='REVIEW'"));}
 @Test void policyRevocationDuringCentralFetchForcesReview()throws Exception{agent.close();agent=new AgentService(store,acl,(a,d)->{assertEquals(false,d.get("autoPublish"));return Map.of("state","SUBMITTED","id",UUID.randomUUID().toString());},(policy,observations,draft)->{store.tx(db->{exec(db,"UPDATE agent_config SET revision=revision+1");return null;});return new AgentService.EvidenceProof(true,"SOURCE_MATCH",List.of());});var j=claim();agent.handle(worker,"agent.worker.complete",completion(j));agent.drainOutbox();assertEquals(1,sqlLong("SELECT count(*) FROM agent_candidate WHERE state='REVIEW'"));}
 @Test void workerBoundaryRejectsPrivateAndAdminRpcEvenIfMaterialAclWouldAllow()throws Exception{assertThrows(CommunityException.class,()->agent.enforceWorkerBoundary(worker,"content.library.get"));assertThrows(CommunityException.class,()->agent.enforceWorkerBoundary(worker,"admin.roles.list"));assertDoesNotThrow(()->agent.enforceWorkerBoundary(worker,"agent.worker.claim"));assertDoesNotThrow(()->agent.enforceWorkerBoundary(admin,"agent.status"));}
 @Test void ordinaryReaderCanGetOnlyCityCatalogNotSourceRules()throws Exception{String reader=identity(key());assertEquals(2,((List<?>)agent.handle(reader,"agent.cities.list",Map.of()).get("cities")).size());assertThrows(CommunityException.class,()->agent.handle(reader,"agent.sources.list",Map.of()));}
