 @Test void thousandSourcesAreReturnedWithoutNodeOverflowOrOmission()throws Exception{
  store.tx(db->{for(int n=0;n<998;n++)exec(db,"INSERT INTO agent_source(id,url,city,source_group,official,enabled,min_interval,lawful_basis) VALUES(?,?,'ru/ru-mow/moscow',?,1,1,30,?)",UUID.randomUUID().toString(),"https://source.example/feed/"+n,"independent-"+n,"Synthetic lawful source fixture "+"я".repeat(950));return null;});
  Map<String,Object>first=agent.handle(admin,"agent.sources.list",Map.of());assertEquals(50,((List<?>)first.get("sources")).size());
  assertEquals(1000,pagedRows(admin,"agent.sources.list","sources",100));
 }
 @Test void citiesWorkersJobsAndFullReviewDraftsAllHaveBoundedCompletePages()throws Exception{
  store.tx(db->{for(int n=0;n<998;n++)exec(db,"INSERT INTO agent_city(id,name) VALUES(?,?)","ru/test/city-"+n,"Длинное название города "+n);
   for(int n=0;n<125;n++){String user=identity(key());exec(db,"INSERT INTO agent_worker(identity,enabled) VALUES(?,1)",user);}
   Map<String,Object>draft=new LinkedHashMap<>();draft.put("title","Проверенная новость");draft.put("summary","я".repeat(2000));draft.put("sources",java.util.stream.IntStream.range(0,10).mapToObj(i->"https://source"+i+".example/news").toList());draft.put("sourceGroups",java.util.stream.IntStream.range(0,10).mapToObj(i->"Независимая редакция "+i).toList());draft.put("cityId","ru/ru-mow/moscow");draft.put("eventDate","2026-10-15T00:00:00Z");draft.put("significance","NORMAL");draft.put("verified",true);draft.put("autoPublish",false);draft.put("distribution","CITY");draft.put("dedupe","fixture");
   for(int n=0;n<1000;n++){String id=UUID.randomUUID().toString();exec(db,"INSERT INTO agent_job(id,city,created,state,next_attempt) VALUES(?,'ru/ru-mow/moscow',?,'COMPLETE',0)",id,clock.millis()+n%3);exec(db,"INSERT INTO agent_candidate(id,dedupe,job,state,draft,created) VALUES(?,?,?,'REVIEW',?,?)",UUID.randomUUID().toString(),"synthetic-"+n,id,AgentJson.bytes(draft),clock.millis()+n%3);}return null;});
  String reader=identity(key());assertEquals(1000,pagedRows(reader,"agent.cities.list","cities",100));assertEquals(127,pagedRows(admin,"agent.workers.list","workers",100));assertEquals(1000,pagedRows(admin,"agent.jobs.list","jobs",100));assertEquals(1000,pagedRows(admin,"agent.review.list","items",100));
  assertEquals(25,((List<?>)agent.handle(admin,"agent.review.list",Map.of()).get("items")).size());
 }
 @Test void pageCursorCannotCrossActorEndpointEpochOrExpiry()throws Exception{
  String cursor=(String)agent.handle(admin,"agent.sources.list",Map.of("limit",1)).get("nextCursor");assertFalse(cursor.isEmpty());
  assertThrows(CommunityException.class,()->agent.handle(second,"agent.sources.list",Map.of("cursor",cursor)));
  assertThrows(CommunityException.class,()->agent.handle(admin,"agent.cities.list",Map.of("cursor",cursor)));
  assertThrows(CommunityException.class,()->agent.handle(admin,"agent.sources.list",Map.of("cursor",cursor+"x")));
  store.tx(db->{store.bumpEpoch(db,admin);return null;});assertThrows(CommunityException.class,()->agent.handle(admin,"agent.sources.list",Map.of("cursor",cursor)));
  String fresh=(String)agent.handle(admin,"agent.sources.list",Map.of("limit",1)).get("nextCursor");clock.advance(Duration.ofMinutes(16));assertThrows(CommunityException.class,()->agent.handle(admin,"agent.sources.list",Map.of("cursor",fresh)));
  assertThrows(CommunityException.class,()->agent.handle(admin,"agent.sources.list",Map.of("limit",101)));
 }
